func TestDefinitionCoversWhatRunsButNotEnvironment(t *testing.T) {
	t.Parallel()
	npx := "npx"
	base := Server{Command: &npx, Args: []string{"-y", "some-mcp"}, Env: map[string]string{"API_KEY": "one"}}
	rotated := base
