	stale := func(want bool) {
		t.Helper()
		report, err := NewService().Preflight(definition, options)
		if err != nil {
			t.Fatal(err)
		}
		found := false
		for _, finding := range report.Findings {
			found = found || finding.Code == "STAGING_INPUTS_STALE"
		}
